int * binary_search(int val) {
    unsigned int L = 0, R = array_length(arr), M;
    while (L < R) {
        M = (L + R - 1) / 2;
        if (val == arr[M])
            return arr + M; /* found */
        else if (val < arr[M])
            R = M; /* in first half */
        else
            L = M + 1; /* in second half */
    }
    return NULL; /* not found */
}

